import { Prism, languages } from '../prismCore'
import './markup-templating'

var smartyPattern = /\{\*[\s\S]*?\*\}|\{php\}[\s\S]*?\{\/php\}|\{(?:[^{}"']|"(?:\\.|[^"\\\r\n])*"|'(?:\\.|[^'\\\r\n])*'|\{(?:[^{}"']|"(?:\\.|[^"\\\r\n])*"|'(?:\\.|[^'\\\r\n])*'|\{(?:[^{}"']|"(?:\\.|[^"\\\r\n])*"|'(?:\\.|[^'\\\r\n])*')*\})*\})*\}/g;

var embedInside = {
	pattern: /^\{php\}|\{\/php\}$/
};

var expression = {
	pattern: /[\s\S]+/
};

var smarty = embedInside.inside = expression.inside = languages.smarty = {
	'comment': {
		pattern: /^\{\*[\s\S]*?\*\}/,
		greedy: true
	},
	'embedded-php': {
		pattern: /^\{php\}[\s\S]*?\{\/php\}/,
		greedy: true,
		inside: {
			'smarty': embedInside,
			'php': {
				pattern: /[\s\S]+/,
				alias: 'language-php',
				inside: 'php'
			}
		}
	},
	'string': [
		{
			pattern: /"(?:\\.|[^"\\\r\n])*"/,
			greedy: true,
			inside: {
				'interpolation': {
					pattern: /\{[^{}]*\}|`[^`]*`/,
					inside: {
						'interpolation-punctuation': {
							pattern: /^[{`]|[`}]$/,
							alias: 'punctuation'
						},
						'expression': expression
					}
				},
				'variable': /\$\w+/
			}
		},
		{
			pattern: /'(?:\\.|[^'\\\r\n])*'/,
			greedy: true
		},
	],
	'keyword': {
		pattern: /(^\{\/?)[a-z_]\w*\b(?!\()/i,
		lookbehind: true,
		greedy: true
	},
	'delimiter': {
		pattern: /^\{\/?|\}$/,
		greedy: true,
		alias: 'punctuation'
	},
	'number': /\b0x[\dA-Fa-f]+|(?:\b\d+(?:\.\d*)?|\B\.\d+)(?:[Ee][-+]?\d+)?/,
	'variable': [
		/\$(?!\d)\w+/,
		/#(?!\d)\w+#/,
		{
			pattern: /(\.|->|\w\s*=)(?!\d)\w+\b(?!\()/,
			lookbehind: true
		},
		{
			pattern: /(\[)(?!\d)\w+(?=\])/,
			lookbehind: true
		}
	],
	'function': {
		pattern: /(\|\s*)@?[a-z_]\w*|\b[a-z_]\w*(?=\()/i,
		lookbehind: true
	},
	'attr-name': /\b[a-z_]\w*(?=\s*=)/i,
	'boolean': /\b(?:false|no|off|on|true|yes)\b/,
	'punctuation': /[\[\](){}.,:`]|->/,
	'operator': [
		/[+\-*\/%]|==?=?|[!<>]=?|&&|\|\|?/,
		/\bis\s+(?:not\s+)?(?:div|even|odd)(?:\s+by)?\b/,
		/\b(?:and|eq|gt?e|gt|lt?e|lt|mod|neq?|not|or)\b/
	]
};

// Tokenize all inline Smarty expressions
Prism.hooks.add('before-tokenize', env => {
	var smartyLiteralStart = '{literal}';
	var smartyLiteralEnd = '{/literal}';
	var smartyLiteralMode = false;

	languages['markup-templating'].buildPlaceholders(env, 'smarty', smartyPattern, match => {
		// Smarty tags inside {literal} block are ignored
		if (match == smartyLiteralEnd) {
			smartyLiteralMode = false;
		}

		if (!smartyLiteralMode) {
			if (match == smartyLiteralStart) {
				smartyLiteralMode = true;
			}

			return true;
		}
		return false;
	});
});

// Re-insert the tokens after tokenizing
Prism.hooks.add('after-tokenize', env => {
	languages['markup-templating'].tokenizePlaceholders(env, 'smarty');
});
